#[derive(Debug, Hash, Deserialize, Serialize, JsonSchema, Validate, Anonymize, Clone, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub struct SparseVectorParams {
    /// Custom params for index. If none - values from collection configuration are used.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub index: Option<SparseIndexParams>,
    /// Configures addition value modifications for sparse vectors.
    /// Default: none
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub modifier: Option<Modifier>,
}
// Plain derived Deserialize: serde's struct visitor accepts BOTH map and positional-seq input; with every field #[serde(default)], an empty JSON array [] deserializes to the all-None default struct. No deny_unknown_fields, no custom Deserialize, no check that input was a JSON object.

